import React, { useRef, useEffect, useImperativeHandle, forwardRef } from 'react';
import p5Types from 'p5'; // Just for types
import { ComponentType, CircuitComponent, Wire, Point, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_BG, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE, COLOR_GRID, COLOR_WIRE_OFF, COLOR_WIRE_ON } from '../constants';
import { stepSimulation } from '../logic/circuitEngine';

// Extend Window interface to allow global p5 usage if needed
declare global {
  interface Window {
    p5: any;
  }
}

export interface LogicCanvasHandle {
  getData: () => { components: CircuitComponent[], wires: Wire[] };
  updateSelectedComponent: (updates: Partial<CircuitComponent>) => void;
  deleteSelected: () => void;
}

interface LogicCanvasProps {
  tool: 'SELECT' | 'DELETE';
  isPlaying: boolean;
  tickSpeedMs: number; 
  pendingDrop?: { type: ComponentType, x: number, y: number, functionId?: string } | null;
  initialComponents: CircuitComponent[];
  initialWires: Wire[];
  functionLibrary: FunctionCircuit[];
  onPendingDropHandled?: () => void;
  onSelectionChange?: (component: CircuitComponent | null) => void;
}

interface ViewportState {
  x: number;
  y: number;
  zoom: number;
}

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

// Helpers for Sorting / Layout
const getSide = (c: CircuitComponent, isInput: boolean): PortSide => {
    if (c.icPortSide) return c.icPortSide;
    // Default Visual Defaults: Input Switch points Right (Source), Output LED points Left (Sink)
    return isInput ? 'right' : 'left';
};
const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };
const sortComponents = (components: CircuitComponent[], isInput: boolean) => {
    return components.sort((a, b) => {
        const sideA = getSide(a, isInput);
        const sideB = getSide(b, isInput);
        if (sideOrder[sideA] !== sideOrder[sideB]) return sideOrder[sideA] - sideOrder[sideB];
        if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
        return a.y - b.y;
    });
};

const LogicCanvas = forwardRef<LogicCanvasHandle, LogicCanvasProps>(({ 
  tool, 
  isPlaying, 
  tickSpeedMs, 
  pendingDrop, 
  initialComponents,
  initialWires,
  functionLibrary,
  onPendingDropHandled,
  onSelectionChange
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const p5InstanceRef = useRef<p5Types | null>(null);

  // -- Simulation State --
  const componentsRef = useRef<CircuitComponent[]>(JSON.parse(JSON.stringify(initialComponents)));
  const wiresRef = useRef<Wire[]>(JSON.parse(JSON.stringify(initialWires)));

  // -- Selection & Interaction State --
  const selectedCompId = useRef<string | null>(null); // Highlighted / Editing
  const activeDragId = useRef<string | null>(null);   // Currently physically moving

  // -- Expose state to parent --
  useImperativeHandle(ref, () => ({
    getData: () => ({
        components: componentsRef.current,
        wires: wiresRef.current
    }),
    updateSelectedComponent: (updates: Partial<CircuitComponent>) => {
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) {
                Object.assign(comp, updates);
            }
        }
    },
    deleteSelected: () => {
        if (selectedCompId.current) {
             const id = selectedCompId.current;
             componentsRef.current = componentsRef.current.filter(c => c.id !== id);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== id && w.toCompId !== id);
             selectedCompId.current = null;
             activeDragId.current = null;
             if(onSelectionChange) onSelectionChange(null);
        }
    }
  }));

  // -- Refs for Props --
  const tickSpeedRef = useRef(tickSpeedMs);
  const isPlayingRef = useRef(isPlaying);
  const toolRef = useRef(tool);
  const libraryRef = useRef(functionLibrary);

  useEffect(() => { tickSpeedRef.current = tickSpeedMs; }, [tickSpeedMs]);
  useEffect(() => { isPlayingRef.current = isPlaying; }, [isPlaying]);
  useEffect(() => { toolRef.current = tool; }, [tool]);
  useEffect(() => { libraryRef.current = functionLibrary; }, [functionLibrary]);

  // -- Viewport / Camera State --
  const viewportRef = useRef<ViewportState>({ x: 0, y: 0, zoom: 1.0 });
  const isPanningRef = useRef<boolean>(false);

  // -- Interaction State --
  const isDraggingComp = useRef<boolean>(false); // Distinguish click vs drag
  const wiringStart = useRef<{ compId: string, portIndex: number, type: 'input'|'output' } | null>(null);
  const dragOffset = useRef<Point>({ x: 0, y: 0 }); 

  const accumulatorRef = useRef<number>(0);

  const screenToWorld = (sx: number, sy: number): Point => {
    return {
      x: (sx - viewportRef.current.x) / viewportRef.current.zoom,
      y: (sy - viewportRef.current.y) / viewportRef.current.zoom
    };
  };

  const addComponent = (type: ComponentType, screenX: number, screenY: number, functionId?: string) => {
    const worldPos = screenToWorld(screenX, screenY);
    let def = COMPONENT_DEFINITIONS[type];

    // For Custom ICs, dynamic inputs/outputs
    let inputsCount = def.inputs;
    let outputsCount = def.outputs;
    let internalState = undefined;
    let label = def.label;

    if (type === ComponentType.CUSTOM_IC && functionId) {
        const func = libraryRef.current.find(f => f.id === functionId);
        if (func) {
            inputsCount = func.components.filter(c => c.type === ComponentType.INPUT_SWITCH).length;
            outputsCount = func.components.filter(c => c.type === ComponentType.OUTPUT_LED).length;
            label = func.name;
            // Clone internal state for this instance
            internalState = {
                components: JSON.parse(JSON.stringify(func.components)),
                wires: JSON.parse(JSON.stringify(func.wires))
            };
        }
    }

    const snapX = Math.round(worldPos.x / GRID_SIZE) * GRID_SIZE;
    const snapY = Math.round(worldPos.y / GRID_SIZE) * GRID_SIZE;

    const newComp: CircuitComponent = {
      id: crypto.randomUUID(),
      type: type,
      x: snapX,
      y: snapY,
      inputValues: new Array(inputsCount).fill(false),
      outputValues: new Array(outputsCount).fill(false),
      functionId: functionId,
      internalState: internalState,
      customLabel: type === ComponentType.CUSTOM_IC ? label : undefined
    };

    componentsRef.current.push(newComp);
    // Auto-select new component
    selectedCompId.current = newComp.id;
    if (onSelectionChange) onSelectionChange(newComp);
  };

  useEffect(() => {
    if (pendingDrop) {
      addComponent(pendingDrop.type, pendingDrop.x, pendingDrop.y, pendingDrop.functionId);
      if (onPendingDropHandled) onPendingDropHandled();
    }
  }, [pendingDrop, onPendingDropHandled]);

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    try {
        const data = e.dataTransfer.getData('application/react-logic-sim');
        if (data) {
            const parsed = JSON.parse(data);
            const { type, functionId } = parsed;

            if (containerRef.current) {
                const rect = containerRef.current.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;
                addComponent(type, x, y, functionId);
            }
        }
    } catch(err) {
        console.error("Drop failed", err);
    }
  };

  // -- P5 Setup --
  useEffect(() => {
    if (!containerRef.current) return;

    const p5Constructor = (window as any).p5;
    if (!p5Constructor) return;

    if (p5InstanceRef.current) {
        p5InstanceRef.current.remove();
    }

    const sketch = (p: p5Types) => {
      let pinchDistStart = 0;
      let lastTouchX = 0;
      let lastTouchY = 0;
      let isCanvasInteraction = false;

      p.setup = () => {
        p.createCanvas(containerRef.current!.clientWidth, containerRef.current!.clientHeight);
        p.frameRate(60);
        p.textSize(10);
        p.textAlign(p.CENTER, p.CENTER);
        document.oncontextmenu = () => false; 
      };

      p.windowResized = () => {
        if(containerRef.current) {
          p.resizeCanvas(containerRef.current.clientWidth, containerRef.current.clientHeight);
        }
      };

      p.draw = () => {
        p.background(COLOR_BG);

        if (isPlayingRef.current) {
          accumulatorRef.current += p.deltaTime;
          if (accumulatorRef.current > 500) accumulatorRef.current = 500;

          const speed = tickSpeedRef.current;
          while (accumulatorRef.current >= speed) {
            // Pass library for recursive simulation
            const result = stepSimulation(componentsRef.current, wiresRef.current, libraryRef.current);
            componentsRef.current = result.components;
            wiresRef.current = result.wires;
            accumulatorRef.current -= speed;
          }
        } else {
          accumulatorRef.current = 0;
        }

        p.push();
        p.translate(viewportRef.current.x, viewportRef.current.y);
        p.scale(viewportRef.current.zoom);

        // Grid
        const visibleL = -viewportRef.current.x / viewportRef.current.zoom;
        const visibleT = -viewportRef.current.y / viewportRef.current.zoom;
        const visibleR = (p.width - viewportRef.current.x) / viewportRef.current.zoom;
        const visibleB = (p.height - viewportRef.current.y) / viewportRef.current.zoom;

        const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
        const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
        const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
        const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

        p.stroke(COLOR_GRID);
        p.strokeWeight(1 / viewportRef.current.zoom); 

        for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
        for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);

        // Wires
        wiresRef.current.forEach(wire => {
          const fromComp = componentsRef.current.find(c => c.id === wire.fromCompId);
          const toComp = componentsRef.current.find(c => c.id === wire.toCompId);
          if (fromComp && toComp) {
            const start = getPortPosition(fromComp, wire.fromPortIndex, 'output');
            const end = getPortPosition(toComp, wire.toPortIndex, 'input');

            p.stroke(wire.state ? COLOR_WIRE_ON : COLOR_WIRE_OFF);
            p.strokeWeight(wire.state ? 3 : 2);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = getWireControlPoint(start, cpOffset);
            const cp2 = getWireControlPoint(end, cpOffset);

            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
          }
        });

        // Temp Wire (Dragging)
        if (wiringStart.current) {
          const comp = componentsRef.current.find(c => c.id === wiringStart.current!.compId);
          if (comp) {
            const start = getPortPosition(comp, wiringStart.current.portIndex, wiringStart.current.type);
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

            p.stroke(COLOR_WIRE_OFF);
            p.strokeWeight(2);
            p.noFill();

            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = getWireControlPoint(start, cpOffset);

            // Calculate pseudo CP2 based on whether we are dragging from an Output (finding Input) or Input (finding Output)
            let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
            if (wiringStart.current.type === 'output') {
                 // Dragging source -> dest (seeking input)
                 // Inputs usually enter from Left, so bias CP2 to the left of mouse
                 cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
            } else {
                 // Dragging dest -> source (seeking output)
                 // Outputs usually exit to Right, so bias CP2 to right of mouse
                 cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
            }

            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
          }
        }

        // Components
        componentsRef.current.forEach(comp => {
          drawComponent(p, comp);
        });

        // Selection Highlight
        if (selectedCompId.current) {
            const comp = componentsRef.current.find(c => c.id === selectedCompId.current);
            if (comp) {
                const dims = getComponentDimensions(comp);
                p.noFill();
                p.stroke('#3b82f6');
                p.strokeWeight(2);
                const pad = 4;
                p.rect(comp.x - pad, comp.y - pad, (dims.w * GRID_SIZE) + (pad*2), (dims.h * GRID_SIZE) + (pad*2), 4);
            }
        }

        // Hover Highlights (Ports)
        // Check mouse world position for hover effect
        if (!wiringStart.current && !activeDragId.current) {
            const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
            const hPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
            if (hPort) {
                const comp = componentsRef.current.find(c => c.id === hPort.compId);
                if (comp) {
                    const pos = getPortPosition(comp, hPort.portIndex, hPort.type);
                    p.noFill();
                    p.stroke('#3b82f6'); // Blue highlight
                    p.strokeWeight(2);
                    p.circle(pos.x, pos.y, 14);
                }
            }
        }

        p.pop();
      };

      const getWireControlPoint = (pt: PortPoint, offset: number) => {
        if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
        if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
        if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
        return { x: pt.x + offset, y: pt.y }; // right
      };

      const getComponentDimensions = (comp: CircuitComponent) => {
          const def = COMPONENT_DEFINITIONS[comp.type];
          if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
             const funcDef = libraryRef.current.find(f => f.id === comp.functionId);
             if (funcDef) {
                // Calculate size based on ports on each side
                const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
                const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

                const topCount = inputs.filter(c => getSide(c, true) === 'top').length + outputs.filter(c => getSide(c, false) === 'top').length;
                const bottomCount = inputs.filter(c => getSide(c, true) === 'bottom').length + outputs.filter(c => getSide(c, false) === 'bottom').length;
                const leftCount = inputs.filter(c => getSide(c, true) === 'left').length + outputs.filter(c => getSide(c, false) === 'left').length;
                const rightCount = inputs.filter(c => getSide(c, true) === 'right').length + outputs.filter(c => getSide(c, false) === 'right').length;

                const width = Math.max(2, topCount, bottomCount);
                const height = Math.max(3, leftCount, rightCount);
                return { w: width, h: height, inputs: 0, outputs: 0 }; // inputs/outputs counts unused for layout here
             }
             return { w: 3, h: 3, inputs: 0, outputs: 0 };
          }
          return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
      };

      const getPortPosition = (comp: CircuitComponent, index: number, type: 'input' | 'output'): PortPoint => {
        const dims = getComponentDimensions(comp);
        const w = dims.w * GRID_SIZE;
        const h = dims.h * GRID_SIZE;

        // Dynamic pin position for Input/Output components based on side selection
        if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
            const side = comp.icPortSide || 'right'; // Default to Right
            if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
            if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
            if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
            if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
        }
        if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
            const side = comp.icPortSide || 'left'; // Default to Left
            if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
            if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
            if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
            if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
        }

        if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
             const funcDef = libraryRef.current.find(f => f.id === comp.functionId);
             if (funcDef) {
                 const targetGroup = type === 'input' 
                    ? sortComponents(funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH), true)
                    : sortComponents(funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED), false);

                 const targetComp = targetGroup[index];
                 if (targetComp) {
                     const side = getSide(targetComp, type === 'input');
                     const sideGroup = targetGroup.filter(c => getSide(c, type === 'input') === side);
                     const localIndex = sideGroup.indexOf(targetComp);
                     const count = sideGroup.length;

                     if (side === 'top') {
                         const step = w / (count + 1);
                         return { x: comp.x + ((localIndex + 1) * step), y: comp.y, side: 'top' };
                     } else if (side === 'bottom') {
                         const step = w / (count + 1);
                         return { x: comp.x + ((localIndex + 1) * step), y: comp.y + h, side: 'bottom' };
                     } else if (side === 'left') {
                         const step = h / (count + 1);
                         return { x: comp.x, y: comp.y + ((localIndex + 1) * step), side: 'left' };
                     } else { // right
                         const step = h / (count + 1);
                         return { x: comp.x + w, y: comp.y + ((localIndex + 1) * step), side: 'right' };
                     }
                 }
             }
        }

        // Standard logic gates
        const count = type === 'input' ? dims.inputs : dims.outputs;
        const yStep = h / (count + 1);
        return {
          x: type === 'input' ? comp.x : comp.x + w,
          y: comp.y + ((index + 1) * yStep),
          side: type === 'input' ? 'left' : 'right'
        };
      };

      const drawArrow = (p: p5Types, x: number, y: number, side: PortSide, size: number) => {
          p.push();
          p.translate(x, y);
          if (side === 'right') p.rotate(0);
          else if (side === 'bottom') p.rotate(p.HALF_PI);
          else if (side === 'left') p.rotate(p.PI);
          else if (side === 'top') p.rotate(-p.HALF_PI);

          p.triangle(-size, -size/2, 0, 0, -size, size/2);
          p.pop();
      };

      const drawComponent = (p: p5Types, comp: CircuitComponent) => {
        const dims = getComponentDimensions(comp);
        const w = dims.w * GRID_SIZE;
        const h = dims.h * GRID_SIZE;
        const inputs = dims.inputs;
        const outputs = dims.outputs;

        const py = 6;
        const padX = 4;
        const effectiveH = h - (py * 2);

        p.push();
        p.translate(comp.x, comp.y);

        // Body
        p.fill(COLOR_COMPONENT_BG);
        p.stroke(COLOR_COMPONENT_STROKE);
        p.strokeWeight(2);

        if (comp.type === ComponentType.CUSTOM_IC) {
            // ... (IC Rendering logic unchanged)
            p.rect(0, 0, w, h, 4);
            p.fill('#1e293b');
            p.noStroke();
            p.textSize(12);
            p.textStyle(p.BOLD);
            p.textAlign(p.CENTER, p.CENTER);
            p.text(comp.customLabel || "IC", w/2, h/2);

            p.textSize(8);
            p.textStyle(p.NORMAL);
            const funcDef = libraryRef.current.find(f => f.id === comp.functionId);
            if (funcDef) {
                 const drawPin = (c: CircuitComponent, isInput: boolean) => {
                     const side = getSide(c, isInput);
                     const group = isInput 
                        ? sortComponents(funcDef.components.filter(x => x.type === ComponentType.INPUT_SWITCH), true)
                        : sortComponents(funcDef.components.filter(x => x.type === ComponentType.OUTPUT_LED), false);
                     const sideGroup = group.filter(x => getSide(x, isInput) === side);
                     const localIndex = sideGroup.indexOf(c);
                     const count = sideGroup.length;
                     let px = 0, py = 0;
                     p.fill('#64748b');
                     if (side === 'top') {
                         px = (localIndex + 1) * (w / (count + 1));
                         py = 0;
                         p.circle(px, py, 4);
                         p.textAlign(p.CENTER, p.TOP);
                         p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, 6);
                     } else if (side === 'bottom') {
                         px = (localIndex + 1) * (w / (count + 1));
                         py = h;
                         p.circle(px, py, 4);
                         p.textAlign(p.CENTER, p.BOTTOM);
                         p.text(c.customLabel || (isInput ? "IN" : "OUT"), px, h - 6);
                     } else if (side === 'left') {
                         px = 0;
                         py = (localIndex + 1) * (h / (count + 1));
                         p.circle(px, py, 4);
                         p.textAlign(p.LEFT, p.CENTER);
                         p.text(c.customLabel || (isInput ? "IN" : "OUT"), 6, py);
                     } else {
                         px = w;
                         py = (localIndex + 1) * (h / (count + 1));
                         p.circle(px, py, 4);
                         p.textAlign(p.RIGHT, p.CENTER);
                         p.text(c.customLabel || (isInput ? "IN" : "OUT"), w - 6, py);
                     }
                 };
                 funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH).forEach(c => drawPin(c, true));
                 funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED).forEach(c => drawPin(c, false));
            }

        } else if (comp.type === ComponentType.INPUT_SWITCH) {
            const isOn = comp.outputValues[0];
            const side = comp.icPortSide || 'right';

            // Draw Connection Line and Port Node
            p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
            let portX = 0, portY = 0;

            if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
            else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
            else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
            else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

            // Port Node
            p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

            // Body
            p.stroke(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_STROKE);
            p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG);

            // Adjust Rect for vertical vs horizontal
            p.rect(padX, py, w - (padX*2), effectiveH, 4); 

            // Text Label
            p.noStroke();
            p.fill(isOn ? '#fff' : '#475569');
            p.textSize(9);
            p.push();
            p.translate(w/2, h/2);
            if (side === 'top' || side === 'bottom') p.rotate(-p.HALF_PI); // Rotate text for vertical
            p.text(isOn ? "ON" : "OFF", 0, 0);
            p.pop();

            // Flow Arrow (Pointing towards Pin)
            p.fill(isOn ? '#fff' : '#94a3b8');
            const arrowDist = 12;
            if (side === 'right') drawArrow(p, w - arrowDist, h/2, 'right', 6);
            else if (side === 'left') drawArrow(p, arrowDist, h/2, 'left', 6);
            else if (side === 'top') drawArrow(p, w/2, arrowDist, 'top', 6);
            else if (side === 'bottom') drawArrow(p, w/2, h - arrowDist, 'bottom', 6);

        } else if (comp.type === ComponentType.OUTPUT_LED) {
            const isOn = comp.inputValues[0];
            const side = comp.icPortSide || 'left';

            // Line based on side
            p.stroke(COLOR_COMPONENT_STROKE);
            let portX = 0, portY = 0;
            if (side === 'right') { p.line(w - padX, h/2, w, h/2); portX = w; portY = h/2; }
            else if (side === 'left') { p.line(0, h/2, padX, h/2); portX = 0; portY = h/2; }
            else if (side === 'top') { p.line(w/2, 0, w/2, padX); portX = w/2; portY = 0; }
            else if (side === 'bottom') { p.line(w/2, h - padX, w/2, h); portX = w/2; portY = h; }

            // Port Node
            p.fill('#64748b'); p.noStroke(); p.circle(portX, portY, 6);

            // Body (Always circle/bulb style for LED)
            p.noStroke();
            const r = (Math.min(w, h) - (padX * 2)) / 2;
            if (isOn) {
                p.fill(245, 158, 11, 80); 
                p.circle(w/2, h/2, r * 2.5);
            }
            p.fill(isOn ? COLOR_WIRE_ON : '#334155');
            p.circle(w/2, h/2, r * 2);

            // Flow Arrow (Pointing Away from Pin / Towards Center)
            p.fill('#fff');
            const arrowDist = 10;
            // Opposite of side
            if (side === 'right') drawArrow(p, w - arrowDist, h/2, 'left', 4);
            else if (side === 'left') drawArrow(p, arrowDist, h/2, 'right', 4);
            else if (side === 'top') drawArrow(p, w/2, arrowDist, 'bottom', 4);
            else if (side === 'bottom') drawArrow(p, w/2, h - arrowDist, 'top', 4);

        } else if (['AND', 'NAND', 'OR', 'NOR', 'NOT', 'XOR'].includes(comp.type)) {
             // ... (Standard Gate rendering remains the same)
             const isNegated = ['NAND', 'NOR', 'NOT'].includes(comp.type);
             const bubbleR = 4;
             let bodyW = w;
             if (isNegated) bodyW = w - (bubbleR*2) - 2;

             if (comp.type === 'AND' || comp.type === 'NAND') {
                 p.beginShape(); p.vertex(0, py); p.vertex(bodyW * 0.5, py);
                 p.bezierVertex(bodyW, py, bodyW, h - py, bodyW * 0.5, h - py); p.vertex(0, h - py); p.endShape(p.CLOSE);
             } else if (comp.type === 'NOT') {
                 p.triangle(0, py, 0, h - py, bodyW, h / 2);
             } else if (comp.type === 'OR' || comp.type === 'NOR') {
                 p.beginShape(); p.vertex(0, py); p.bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py);
                 p.bezierVertex(w * 0.5, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
                 p.bezierVertex(bodyW, h/2 - (effectiveH/4), w * 0.5, py, 0, py); p.endShape(p.CLOSE);
             } else if (comp.type === 'XOR') {
                p.noFill(); p.beginShape(); p.vertex(0, py); p.bezierVertex(5, h * 0.25, 5, h * 0.75, 0, h - py); p.endShape();
                p.fill(COLOR_COMPONENT_BG); p.beginShape(); p.vertex(4, py); p.bezierVertex(9, h * 0.25, 9, h * 0.75, 4, h - py);
                p.bezierVertex((w * 0.5) + 4, h - py, bodyW, h/2 + (effectiveH/4), bodyW, h/2);
                p.bezierVertex(bodyW, h/2 - (effectiveH/4), (w * 0.5) + 4, py, 4, py); p.endShape(p.CLOSE);
             }
             if (isNegated) {
                 p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE);
                 p.circle(w - bubbleR - 1, h / 2, bubbleR*2);
             }
        } else if (comp.type === ComponentType.HEX_DISPLAY) {
             const yStep = h / 5;
             for(let i=0; i<4; i++) p.line(0, (i+1) * yStep, padX, (i+1) * yStep);
             p.fill('#0f172a'); p.stroke('#334155'); p.rect(padX, py, w - (padX*2), effectiveH, 4);
             p.noStroke(); p.fill('#ef4444'); p.textSize(16);
             let val = 0;
             if(comp.inputValues[0]) val += 1; if(comp.inputValues[1]) val += 2;
             if(comp.inputValues[2]) val += 4; if(comp.inputValues[3]) val += 8;
             p.text(val.toString(16).toUpperCase(), w/2, h/2 + 1);
        } else {
             p.rect(0, 0, w, h, 4);
        }

        // Custom Labels (Standard gates)
        if (comp.customLabel && comp.type !== ComponentType.CUSTOM_IC) {
          p.noStroke();
          p.fill('#1e293b');
          p.textSize(12);
          p.textStyle(p.BOLD);

          if (comp.type === ComponentType.INPUT_SWITCH) {
             // Label positioning based on rotation
             const side = comp.icPortSide || 'right';
             if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
             else if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
             else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
             else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
          } else if (comp.type === ComponentType.OUTPUT_LED) {
             const side = comp.icPortSide || 'left';
             if (side === 'left') { p.textAlign(p.LEFT, p.BOTTOM); p.text(comp.customLabel, w + 5, h); }
             else if (side === 'right') { p.textAlign(p.RIGHT, p.BOTTOM); p.text(comp.customLabel, -5, h); }
             else if (side === 'top') { p.textAlign(p.CENTER, p.TOP); p.text(comp.customLabel, w/2, h + 2); }
             else if (side === 'bottom') { p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2); }
          } else {
             p.textAlign(p.CENTER, p.BOTTOM); p.text(comp.customLabel, w/2, -2);
          }
          p.textAlign(p.CENTER, p.CENTER);
          p.textStyle(p.NORMAL);
        }

        // Ports (Standard gates excluding Input/Output as they are handled above)
        if (comp.type !== ComponentType.CUSTOM_IC && comp.type !== ComponentType.INPUT_SWITCH && comp.type !== ComponentType.OUTPUT_LED) {
            p.noStroke();
            p.fill('#64748b');
            for (let i = 0; i < inputs; i++) {
               const y = ((i + 1) * (h / (inputs + 1)));
               p.circle(0, y, 4);
            }
            for (let i = 0; i < outputs; i++) {
               const y = ((i + 1) * (h / (outputs + 1)));
               p.circle(w, y, 4);
            }
        }

        // Note: For Input/Output, we already drew the Port Node inside the specific block above

        p.pop();
      };

      const getHoveredPort = (wx: number, wy: number): { compId: string, portIndex: number, type: 'input'|'output' } | null => {
        const HIT_RADIUS = 12;
        for (const comp of componentsRef.current) {
          const dims = getComponentDimensions(comp);
          for (let i = 0; i < dims.inputs; i++) {
            const pos = getPortPosition(comp, i, 'input');
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'input' };
          }
          for (let i = 0; i < dims.outputs; i++) {
            const pos = getPortPosition(comp, i, 'output');
            if (p.dist(wx, wy, pos.x, pos.y) < HIT_RADIUS) return { compId: comp.id, portIndex: i, type: 'output' };
          }
        }
        return null;
      };

      const getHoveredComponent = (wx: number, wy: number): string | null => {
        for (const comp of componentsRef.current) {
          const dims = getComponentDimensions(comp);
          if (wx > comp.x && wx < comp.x + (dims.w * GRID_SIZE) &&
              wy > comp.y && wy < comp.y + (dims.h * GRID_SIZE)) {
            return comp.id;
          }
        }
        return null;
      };

      // -- EVENTS --

      const updateComponentPos = (sx: number, sy: number) => {
          isDraggingComp.current = true;
          const mouseWorld = screenToWorld(sx, sy);
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp) {
            comp.x = Math.round((mouseWorld.x - dragOffset.current.x) / GRID_SIZE) * GRID_SIZE;
            comp.y = Math.round((mouseWorld.y - dragOffset.current.y) / GRID_SIZE) * GRID_SIZE;
          }
      };

      p.touchStarted = (e: any) => {
        if (e.target !== p.canvas) {
          isCanvasInteraction = false;
          return true;
        }
        isCanvasInteraction = true;

        if (p.touches.length === 2) {
          const t0 = p.touches[0];
          const t1 = p.touches[1];
          // @ts-ignore
          pinchDistStart = p.dist(t0.x, t0.y, t1.x, t1.y);
        } else if (p.touches.length === 1) {
          lastTouchX = p.touches[0].x;
          lastTouchY = p.touches[0].y;
          p.mousePressed(undefined); // Call without event to allow logic to proceed
        }
        return false;
      };

      p.touchMoved = (e: any) => {
        if (!isCanvasInteraction) return true;

        if (p.touches.length === 2) {
          const t0 = p.touches[0];
          const t1 = p.touches[1];
          // @ts-ignore
          const currentDist = p.dist(t0.x, t0.y, t1.x, t1.y);

          if (pinchDistStart > 0) {
            const scaleFactor = currentDist / pinchDistStart;
            const newZoom = Math.min(Math.max(viewportRef.current.zoom * scaleFactor, 0.1), 5.0);

            // @ts-ignore
            const cx = (t0.x + t1.x) / 2;
            // @ts-ignore
            const cy = (t0.y + t1.y) / 2;

            const wx = (cx - viewportRef.current.x) / viewportRef.current.zoom;
            const wy = (cy - viewportRef.current.y) / viewportRef.current.zoom;

            viewportRef.current.x = cx - wx * newZoom;
            viewportRef.current.y = cy - wy * newZoom;
            viewportRef.current.zoom = newZoom;

            pinchDistStart = currentDist;
          }
        } else if (p.touches.length === 1) {
          const tx = p.touches[0].x;
          const ty = p.touches[0].y;

          if (activeDragId.current) {
            updateComponentPos(tx, ty);
          } else if (isPanningRef.current) {
            const dx = tx - lastTouchX;
            const dy = ty - lastTouchY;
            viewportRef.current.x += dx;
            viewportRef.current.y += dy;
          }

          lastTouchX = tx;
          lastTouchY = ty;
        }
        return false;
      };

      p.touchEnded = () => {
        if (!isCanvasInteraction) return true;
        if (p.touches.length === 0) p.mouseReleased();
        return false;
      };

      p.mouseWheel = (e: any) => {
        const zoomSensitivity = 0.001;
        const zoomFactor = Math.exp(-e.delta * zoomSensitivity);
        const newZoom = Math.min(Math.max(viewportRef.current.zoom * zoomFactor, 0.1), 5.0);
        const wx = (p.mouseX - viewportRef.current.x) / viewportRef.current.zoom;
        const wy = (p.mouseY - viewportRef.current.y) / viewportRef.current.zoom;
        viewportRef.current.zoom = newZoom;
        viewportRef.current.x = p.mouseX - wx * newZoom;
        viewportRef.current.y = p.mouseY - wy * newZoom;
        return false;
      };

      p.mousePressed = (e: any) => {
        // Stop if the event target is not the canvas (e.g. UI click propagated)
        // If e is undefined (manual call), assume valid canvas interaction (guarded by touchStarted)
        if (e && e.target !== p.canvas) return;

        if (p.mouseX < 0 || p.mouseX > p.width || p.mouseY < 0 || p.mouseY > p.height) return;

        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);
        isDraggingComp.current = false;
        isPanningRef.current = false;

        const port = getHoveredPort(mouseWorld.x, mouseWorld.y);
        if (port) {
            // Check for detaching connection from INPUT ports
            if (port.type === 'input') {
                const existingWireIndex = wiresRef.current.findIndex(w => w.toCompId === port.compId && w.toPortIndex === port.portIndex);
                if (existingWireIndex !== -1) {
                    const existingWire = wiresRef.current[existingWireIndex];
                    // Detach: Remove wire, start wiring from the SOURCE of that wire
                    wiresRef.current.splice(existingWireIndex, 1);
                    wiringStart.current = {
                        compId: existingWire.fromCompId,
                        portIndex: existingWire.fromPortIndex,
                        type: 'output'
                    };
                    return;
                }
            }

          wiringStart.current = port;
          return;
        }

        const compId = getHoveredComponent(mouseWorld.x, mouseWorld.y);
        if (compId) {
          if (toolRef.current === 'DELETE') {
             componentsRef.current = componentsRef.current.filter(c => c.id !== compId);
             wiresRef.current = wiresRef.current.filter(w => w.fromCompId !== compId && w.toCompId !== compId);
             if (selectedCompId.current === compId && onSelectionChange) onSelectionChange(null);
             if (activeDragId.current === compId) activeDragId.current = null;
             return;
          }

          const comp = componentsRef.current.find(c => c.id === compId);
          if (comp) {
             selectedCompId.current = compId;
             activeDragId.current = compId; // Start Dragging
             dragOffset.current = { x: mouseWorld.x - comp.x, y: mouseWorld.y - comp.y };
             if (onSelectionChange) onSelectionChange(comp);
          }
          return;
        }

        // Deselect only if clicking empty space
        selectedCompId.current = null;
        activeDragId.current = null;
        if (onSelectionChange) onSelectionChange(null);
        isPanningRef.current = true;
      };

      p.mouseDragged = () => {
        if (p.touches.length > 0) return;
        if (isPanningRef.current) {
          viewportRef.current.x += (p.mouseX - p.pmouseX);
          viewportRef.current.y += (p.mouseY - p.pmouseY);
          return;
        }
        if (activeDragId.current) {
           updateComponentPos(p.mouseX, p.mouseY);
        }
      };

      p.mouseReleased = () => {
        const mouseWorld = screenToWorld(p.mouseX, p.mouseY);

        // Click Logic (if we pressed and released without moving much)
        // Use activeDragId to see if we were potentially interacting with a component
        if (activeDragId.current && !isDraggingComp.current) {
          const comp = componentsRef.current.find(c => c.id === activeDragId.current);
          if (comp) {
            if (comp.type === ComponentType.INPUT_SWITCH) {
              comp.outputValues[0] = !comp.outputValues[0];
            }
          }
        }

        // Stop dragging immediately
        activeDragId.current = null;
        isDraggingComp.current = false;
        isPanningRef.current = false;

        if (wiringStart.current) {
          const endPort = getHoveredPort(mouseWorld.x, mouseWorld.y);
          if (endPort && endPort.compId !== wiringStart.current.compId) {
            let src = wiringStart.current.type === 'output' ? wiringStart.current : endPort;
            let dst = wiringStart.current.type === 'input' ? wiringStart.current : endPort;

            if (src.type === 'output' && dst.type === 'input') {
              const exists = wiresRef.current.some(w => 
                w.toCompId === dst.compId && w.toPortIndex === dst.portIndex
              );
              if (!exists) {
                wiresRef.current.push({
                  id: crypto.randomUUID(),
                  fromCompId: src.compId,
                  fromPortIndex: src.portIndex,
                  toCompId: dst.compId,
                  toPortIndex: dst.portIndex,
                  state: false
                });
              }
            }
          }
          wiringStart.current = null;
        }
      };
    };

    p5InstanceRef.current = new p5Constructor(sketch, containerRef.current);

    return () => {
      p5InstanceRef.current?.remove();
    };
  }, []); 

  return (
    <div 
      ref={containerRef} 
      className="w-full h-full cursor-crosshair touch-none select-none pointer-events-auto" 
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    />
  );
});

export default LogicCanvas;
